entries[187048] = { ["name"] = "Pattern: Greater Drums of Restoration", ["text"] = "Binds when picked up\nRequires Leatherworking (350)\nRequires Kurenai\n- Honored\nUse: Teaches you how to craft Greater Drums of Restoration.\nSell Price:\nGreater Drums of Restoration\nRequires Leatherworking (350)\nUse: Restores 600 health and mana to party members within 40 yards over 15 sec. Drums can be used while shapeshifted. Cannot affect targets level 80 or higher. (2 Min Cooldown)\n50 Charges\nSell Price:\nRequires Heavy Knothide Leather (6), Nether Dragonscales (4)" }
entries[187049] = { ["name"] = "Pattern: Greater Drums of Speed", ["text"] = "Binds when picked up\nRequires Leatherworking (345)\nRequires Kurenai\n- Honored\nUse: Teaches you how to craft Greater Drums of Speed.\nSell Price:\nGreater Drums of Speed\nRequires Leatherworking (340)\nUse: Increases movement speed of party members within 40 yards by 15%. Lasts 30 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges\nSell Price:\nRequires Heavy Knothide Leather (6), Wind Scales (4)" }
